uint64_t NovaWaitDeadline(NovaTiming::Deadline& deadline,uint64_t frequency,uint64_t period,
                         uint64_t epoch,std::stop_token token) {
    for (;;) {
        const auto now=Common::Timer::QueryPerformanceCounter();
        const auto remaining=deadline.Wait(now,period,epoch);
        if (!remaining || token.stop_requested()) return now;
        const auto us=(remaining*1000000u+frequency-1)/frequency;
        Common::Thread::SleepMicro(static_cast<uint32_t>(std::clamp<uint64_t>(us,1,20000)));
    }
}
