void VideoOutDriver::Impl::VblankThread(std::stop_token token) {
    const auto frequency=Common::Timer::QueryPerformanceFrequency();
    EXIT_IF(!frequency);
    NovaTiming::Deadline deadline;
    bool previous_paused=false;
    while (!token.stop_requested()) {
        const auto refresh=std::max(Config::GetVblankFrequency(),1u);
        const auto period=std::max(frequency/refresh,uint64_t{1});
        const bool paused=NovaRuntime::background.load(std::memory_order_relaxed)||m_presenter.IsGuestPaused();
        if (paused!=previous_paused) {deadline.Reset();previous_paused=paused;}
        NovaWaitDeadline(deadline,frequency,period,NovaRuntime::epoch.load(),token);
        if(token.stop_requested())break;
        if(!paused) {VblankBegin();VblankEnd();}
        deadline.Finish(Common::Timer::QueryPerformanceCounter());
    }
}
