void NovaAndroidNoteGameFrame() {
    NovaRuntime::gameFrames.fetch_add(1,std::memory_order_relaxed);
    static NovaTiming::FrameWindow frames;
    static uint64_t lastReport=0,lastGame=0,lastPresented=0,lastVblank=0,epoch=0;
    const auto now=uint64_t(std::chrono::duration_cast<std::chrono::nanoseconds>(std::chrono::steady_clock::now().time_since_epoch()).count());
    const auto generation=NovaRuntime::epoch.load();
    if(generation!=epoch){frames.Reset();lastReport=0;epoch=generation;}
    frames.Add(now);
    if(!lastReport){lastReport=now;lastGame=NovaRuntime::gameFrames.load();lastPresented=NovaRuntime::presentedFrames.load();lastVblank=NovaRuntime::vblanks.load();}
    if(now-lastReport>=5000000000ull){
        const auto game=NovaRuntime::gameFrames.load(),presented=NovaRuntime::presentedFrames.load(),vblank=NovaRuntime::vblanks.load();
        const double seconds=(now-lastReport)/1e9;
        std::fprintf(stderr,"NOVA_PACING: game_fps=%.2f presented_fps=%.2f vblank_hz=%.2f p50_ms=%.2f p95_ms=%.2f p99_ms=%.2f max_ms=%.2f (completed flips vs successful present submissions; sampled interval window)\n",
