            frames.Percentile(50)/1e6,frames.Percentile(95)/1e6,frames.Percentile(99)/1e6,frames.maximum/1e6);
        frames.Reset();lastReport=now;lastGame=game;lastPresented=presented;lastVblank=vblank;
    }
}
